import {isReducedMotion,motionPreference,setMotionPreference,motionDescription} from './motion.js?v=0.87.0';
import {animateDuel} from './duel.js?v=0.87.0';
import {escapeHTML} from './names.js?v=0.87.0';
export function createTitle({slots,onNew,onLoad,onDownload,onUpload,onError}){
 const root=document.querySelector('#title-screen'),app=document.querySelector('#app');let timer;const duel=animateDuel(root,{onReveal:reveal,onComplete:()=>{duel.stop(false);root.classList.remove('opening');}});
 const reduced=()=>isReducedMotion();const motion=root.querySelector('#title-motion'),motionCopy=root.querySelector('#title-motion-copy');const sync=()=>{motion.value=motionPreference();motionCopy.textContent=motionDescription();};sync();motion.onchange=()=>{setMotionPreference(motion.value);sync();};
 function render(){sync();const saves=slots();root.querySelector('#save-slots').innerHTML=saves.map(({slot,save})=>`<button class="title-slot" data-load-slot="${slot}" ${save?'':'disabled'}><span class="slot-number">${String(slot).padStart(2,'0')}</span><span><b>${save?escapeHTML(save.state.playerName||'Aimon'):'Empty slot'}</b><small>${save?escapeHTML(save.state.wiped?'Expedition lost':save.room==='scrub'?'Dorelem Scrub entrance':save.room==='march'?'Civeton March':save.room==='town'?'Civeton':save.room==='pate'?'Pate’s home':save.room==='trade'?'Trade’s home':'Civeton shop')+' · '+save.state.party.length+' partners':'No expedition saved'}</small></span><span class="slot-time">${save?.savedAt?escapeHTML(new Date(save.savedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short'})):''}</span></button>`).join('');root.querySelectorAll('[data-load-slot]').forEach(b=>b.onclick=()=>onLoad(+b.dataset.loadSlot));}
 function present(state){root.dataset.titleState=state;root.querySelector('#title-menu').hidden=false;root.querySelector('#skip-opening').hidden=true;root.querySelector('#title-continue').hidden=state!=='splash';root.querySelector('.title-choices').hidden=state==='splash';root.querySelector('#title-main-options').hidden=state!=='choices';root.querySelector('#save-slots').hidden=state!=='load';root.querySelector('#title-back').hidden=state==='splash';render();(state==='splash'?root.querySelector('#title-continue'):state==='choices'?root.querySelector('#new-game'):root.querySelector('[data-load-slot]:not(:disabled)')||root.querySelector('#title-back')).focus();}
 function reveal(){clearTimeout(timer);root.classList.add('title-from-ghost');present('splash');}
 function menu(keepFinal=false){duel.stop(!keepFinal);clearTimeout(timer);root.classList.remove('opening');present('splash');}
 function opening(){root.dataset.titleState='opening';root.classList.remove('title-from-ghost');duel.start();root.classList.add('opening');root.querySelector('#title-menu').hidden=true;root.querySelector('#skip-opening').hidden=false;root.querySelector('#skip-opening').focus();clearTimeout(timer);timer=setTimeout(()=>menu(true),14000);}
 root.querySelector('#skip-opening').onclick=()=>{root.classList.remove('title-from-ghost');menu();};root.querySelector('#replay-opening').onclick=opening;root.querySelector('#new-game').onclick=()=>onNew();root.querySelector('#title-continue').onclick=()=>present('choices');root.querySelector('#load-game').onclick=()=>present('load');root.querySelector('#title-download-save').onclick=()=>onDownload();root.querySelector('#title-upload-save').onclick=()=>onUpload();root.querySelector('#title-back').onclick=()=>present(root.dataset.titleState==='load'?'choices':'splash');
 root.addEventListener('click',e=>{if(root.dataset.titleState==='splash'&&!e.target.closest('button')&&!document.querySelector('#modal-root .modal'))present('choices');});
 root.addEventListener('keydown',e=>{if(e.target.matches?.('select,input,textarea'))return;if(root.classList.contains('opening')&&root.querySelector('#title-menu').hidden&&['Enter','Escape',' '].includes(e.key)){e.preventDefault();menu();return;}if(root.dataset.titleState==='splash'&&['Enter',' '].includes(e.key)){e.preventDefault();present('choices');return;}const buttons=[...root.querySelectorAll('button:not(:disabled)')].filter(b=>b.getClientRects().length);const i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Tab'){if(e.shiftKey&&i<=0){e.preventDefault();buttons.at(-1)?.focus();}else if(!e.shiftKey&&i===buttons.length-1){e.preventDefault();buttons[0]?.focus();}}});
 return {show(){app.inert=true;document.body.classList.add('at-title');root.hidden=false;render();reduced()?menu():opening();},hide(){root.classList.remove('title-from-ghost');duel.stop();clearTimeout(timer);root.hidden=true;app.inert=false;document.body.classList.remove('at-title');},render,error(message){onError(message);},menu};
}
export function chapterCard(){return new Promise(resolve=>{const root=document.querySelector('#chapter-card');let timer,finished=false;const finish=()=>{if(finished)return;finished=true;clearTimeout(timer);root.hidden=true;root.classList.remove('chapter-playing');resolve();};root.hidden=false;root.classList.add('chapter-playing');root.querySelector('button').onclick=finish;root.querySelector('button').focus();timer=setTimeout(finish,isReducedMotion()?1600:5200);});}
